ee:message.ee:set-payload:
%dw 2.0
output application/json
ns s http://schemas.xmlsoap.org/soap/envelope/
ns ns2 http://PortalFijaWS.etb.com/lte

var innerXml = read(
    ((((payload.s#Envelope.s#Body.ns2#consultaPermanenciaResponse.return)
        replace "&lt;" with "<")
        replace "&gt;" with ">")
        replace "&#xd;" with "")
        replace "&quot;" with "\"",
    "application/xml"
)

fun clean(obj) =
    obj 
        mapObject ((v, k) -> 
            if (v is Object) 
                (k): clean(v) 
            else 
                (k): v
        )
        filterObject ((v, k) -> 
            v != null and 
            !(v is Object and isEmpty(v))
        )

fun deepClean(o) =
    if (o is Object)
        do {
            var cleaned = clean(o)
            ---
            cleaned filterObject ((v, k) -> 
                not (v is Object and isEmpty(v))
            )
        }
    else o

var clausulaXml = innerXml.replies.reply.response.portalfija_data.clausula default {}
var servicios = clausulaXml filterObject ((v, k) ->
    v is Object and (v.CargoInicial? or v.SaldoActual?)
)
var referencia =
    if (servicios.Internet?) servicios.Internet
    else (valuesOf(servicios)[0] default {})

fun num(v) =
    if (v == null or v == "") 0
    else v as Number

var cargoInicial = (sum(valuesOf(servicios) map ((s) -> num(s.CargoInicial))) default 0) as Number
var saldoActual = (sum(valuesOf(servicios) map ((s) -> num(s.SaldoActual))) default 0) as Number
var cuotasInicial = num(referencia.CuotasInicial)
var cuotasActual = num(referencia.CuotasActual)
var valorPenalidad = 
    if (cuotasInicial > 0) 
        (cargoInicial * ((cuotasInicial - cuotasActual) / cuotasInicial)) as Number
    else 0

---
deepClean({
    clausula: {
        cuenta_padre: clausulaXml.cuenta_padre default null,
        integration_id: clausulaXml.integration_id default null,
        Internet: {
            CargoInicial: cargoInicial,
            SaldoActual: saldoActual,
            CuotasInicial: referencia.CuotasInicial default null,
            CuotasActual: referencia.CuotasActual default null,
            fecha_inicio: referencia.fecha_inicio default null,
            fecha_fin: referencia.fecha_fin default null
        },
        valor_penalidad: valorPenalidad
    },
    resultado: innerXml.replies.reply.response.portalfija_data.resultado,
    descError: innerXml.replies.reply.response.portalfija_data.descError
})
